@app.post("/api/auth/signup")
@limiter.limit("5/minute")
def signup(request: Request, user: SignupRequest):
    # Plain `def`: FastAPI runs it in a worker thread, so the ~150 ms PBKDF2 hash
    # no longer blocks the event loop.
