def create_token(user_id: str, secret: bytes, ttl: int = TOKEN_TTL_SECONDS) -> str:
    now = int(time.time())
    payload = {"sub": user_id, "iat": now, "exp": now + ttl}
    signing_input = (
        _b64e(json.dumps(_HEADER, separators=(",", ":")).encode())
        + "."
        + _b64e(json.dumps(payload, separators=(",", ":")).encode())
    )
    sig = hmac.new(secret, signing_input.encode("ascii"), hashlib.sha256).digest()
    return f"{signing_input}.{_b64e(sig)}"

def compare(collection, db_path: str) -> Report:
    all_files, with_questions, pending = sqlite_state(db_path)
    docs = chroma_file_ids(collection)

    report = Report(chroma_total=len(docs), pending_deletions=sorted(pending))
    for cid, fid in sorted(docs.items()):
        if fid not in all_files:
            report.orphan_ids.append(cid)
            report.orphan_file_ids.add(fid)
    indexed = {fid for fid in docs.values() if fid}
    report.unindexed_file_ids = sorted(with_questions - indexed)
    return report

def _delete_file_everywhere(file_id: str, indexer=None) -> Optional[str]:
    """
    Remove a file's embeddings, then its SQLite rows. Chroma goes first so a failure leaves the
    DB rows in place (and the file recorded in `pending_deletions`) instead of orphan embeddings
    that still hold the user's text. Returns None on success, else the error text.
    """
    try:
        (indexer or VectorIndexer()).delete_embeddings_for_file(file_id)
    except Exception as e:
        attempts = db.record_pending_deletion(file_id, str(e))
        logger.warning(
            f"Chroma cleanup failed for {file_id[:8]} (attempt {attempts}); "
            f"keeping DB rows for a retry: {e}"
        )
        return str(e)
    if not db.delete_file(file_id) and db.get_file_name(file_id) is not None:
        db.record_pending_deletion(file_id, "database delete failed")
        return "database delete failed"
    return None  # delete_file also cleared any pending_deletions row

def list_pending_deletions(self) -> List[Dict[str, Any]]:
    with self._connection() as con:
        rows = con.execute(
            "SELECT file_id, attempts, last_error, updated_at FROM pending_deletions "
            "ORDER BY updated_at"
        ).fetchall()
    return [dict(r) for r in rows]

def clear_pending_deletion(self, file_id: str) -> None:
    with self._connection() as con:
        con.execute("DELETE FROM pending_deletions WHERE file_id = ?", (file_id,))

def _process_chunk(self, chunk: Dict, context_str: str) -> Tuple[bool, str]:
    """
    Enrich one chunk. Raises LLMUnavailable if the server fails; in that case nothing is
    left behind for the chunk (no rejection rows, no enrichment row), so it stays pending.
    """
    self.llm.reset_stats()
    try:
        return self._process_chunk_impl(chunk, context_str)
    except LLMUnavailable:
        # get_pending_files() treats an enrichment row as "attempted"; drop it.
        self.db.delete_enrichment(chunk["chunk_id"])
        raise
    finally:
        st = self.llm.stats
        if st["calls"]:
            logger.info(
                f"Chunk {chunk['chunk_id'][:8]}: {st['calls']} LLM call(s), "
                f"{st['seconds']:.1f}s, tokens in/out "
                f"{st['prompt_tokens']}/{st['completion_tokens']}"
            )

def evaluate_turn(self, user_text: str) -> Dict:
    if self.state == InterviewState.TERMINAL:
        return {"error": "Session complete. No more questions available."}

    q = self.ctx.current_question
    if not q:
        return {"error": "No active question."}

    result = self.logic.analyze_response(q, user_text)
    result.timestamp = datetime.now(timezone.utc).isoformat()
    self.ctx.history.append(result)

    alpha = DIFFICULTY_ALPHA
    self.ctx.difficulty_score = (
        alpha * result.confidence + (1 - alpha) * self.ctx.difficulty_score
    )
    if self.ctx.difficulty_score > DIFFICULTY_HARD_ABOVE:
        self.ctx.difficulty_label = "Hard"
    elif self.ctx.difficulty_score < DIFFICULTY_EASY_BELOW:
        self.ctx.difficulty_label = "Easy"
    else:
        self.ctx.difficulty_label = "Medium"

    self.ctx.current_question = self.logic.select_next_question(
        self.ctx.difficulty_label, self.used_ids
    )
    is_terminal = self.ctx.current_question is None
    if not is_terminal:
        self.used_ids.add(self.ctx.current_question.id)
    else:
        self.state = InterviewState.TERMINAL

    return {
        "evaluation": {
            "similarity": result.similarity,
            "bi_score": result.bi_score,
            "lexical_score": result.lexical_score,
            "length_ratio": result.length_ratio,
            "confidence": result.confidence,
            "feedback": result.feedback,
            "grader": result.grader,
            "nli_verdict": result.nli.verdict if result.nli else None,
            "nli_scores": {
                "entailment": round(result.nli.p_entailment, 3),
                "neutral": round(result.nli.p_neutral, 3),
                "contradiction": round(result.nli.p_contradiction, 3),
            }
            if result.nli
            else None,
        },
        "next_question": (
            self.ctx.current_question.text if self.ctx.current_question else None
        ),
        "is_terminal": is_terminal,
    }

def difficulty_instructions(self, content_type: str) -> Dict[str, str]:
    if content_type == "math":
        return {
            "Easy": "definition or notation — ask what a symbol, term, or operator means",
            "Medium": "computation — ask what the formula computes or what its components represent",
            "Hard": "derivation or proof — ask why the formula takes this form, what assumption it relies on, or what happens if a constraint is relaxed",
        }
    return {
        "Easy": "factual recall — ask about specific definitions, names, or stated facts",
        "Medium": "conceptual / mechanism — ask how or why something works",
        "Hard": "analytical / critical — ask about limitations, trade-offs, or comparisons",
    }

@app.get("/api/events")
async def sse_events(request: Request, ticket: Optional[str] = None):
    """Status stream. Needs a ticket from POST /api/events/ticket (or a normal bearer token)."""
    user_id = _redeem_sse_ticket(ticket) if ticket else None
    if user_id and not await run_in_threadpool(db.get_user_by_id, user_id):
        user_id = None
    if not user_id:
        user_id = get_current_user(request)  # 401 for anonymous callers

    queue: asyncio.Queue = asyncio.Queue(maxsize=200)
    _sse_clients[queue] = user_id

    async def event_generator():
        try:
            while True:
                if await request.is_disconnected():
                    break
                try:
                    msg = await asyncio.wait_for(queue.get(), timeout=15.0)
                    yield f"data: {msg}\n\n"
                except asyncio.TimeoutError:
                    yield ": heartbeat\n\n"
        except asyncio.CancelledError:
            pass
        finally:
            _sse_clients.pop(queue, None)

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )

