class LLMClient:

def __init__(
    self,
    base_url: str,
    api_key: str = "no-key",
    timeout: float = LLM_TIMEOUT_S,
    max_retries: int = LLM_MAX_RETRIES,
    prompts: Optional[PromptSet] = None,
):
    self.prompts = prompts or get_prompt_set()  # QP_PROMPT_SET, see prompts.py
    self.client = OpenAI(
        base_url=base_url,
        api_key=api_key,
        timeout=httpx.Timeout(timeout, connect=5.0),
        max_retries=max_retries,
    )
    self.stats = self._empty_stats()

# ---------------- transport ----------------

@staticmethod
def _empty_stats() -> Dict[str, float]:
    return {"calls": 0, "seconds": 0.0, "prompt_tokens": 0, "completion_tokens": 0}

def reset_stats(self) -> None:
    self.stats = self._empty_stats()

@staticmethod
def _max_tokens(answer_tokens: int) -> int:
    budget = REASONING_BUDGET if REASONING_BUDGET >= 0 else UNLIMITED_REASONING_CAP
    return budget + answer_tokens

@dataclass(frozen=True)
class IngestResult:
    """Outcome of ingest(). `status` is one of ok | duplicate | failed."""

    status: Literal["ok", "duplicate", "failed"]
    file_id: Optional[str] = None  # set when status == "ok"
    duplicate_of: Optional[str] = None  # set when status == "duplicate"
    message: str = ""

    @property
    def ok(self) -> bool:
        return self.status == "ok"

@lru_cache(maxsize=1)
def get_device() -> str:
    override = os.environ.get("QP_DEVICE", "").strip().lower()
    if override:
        logger.info(f"Device forced by QP_DEVICE: {override}")
        return override

    try:
        import torch
    except ImportError:
        logger.info("torch not importable — using cpu")
        return "cpu"

    if torch.cuda.is_available():
        logger.info(f"Using GPU: {torch.cuda.get_device_name(0)} (cuda)")
