def parse_dotenv(text: str) -> Dict[str, str]:
    out: Dict[str, str] = {}
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        m = _LINE.match(raw)
        if not m:
            continue
        key, value = m.groups()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
            value = value[1:-1]
        elif " #" in value:  # trailing comment on an unquoted value
            value = value.split(" #", 1)[0].rstrip()
        out[key] = value
    return out

def find_dotenv() -> Optional[Path]:
    """QP_ENV_FILE if set, else the first `.env` in the working directory or above, else next to the packages."""
    explicit = os.environ.get("QP_ENV_FILE")
    if explicit:
        return Path(explicit)
    for start in (Path.cwd(), Path(__file__).resolve()):
        for folder in (start, *start.parents):
            candidate = folder / ".env"
            if candidate.is_file() and (folder / "pyproject.toml").is_file():
                return candidate
    return None

def _process_chunk(self, chunk: Dict, context_str: str) -> Tuple[bool, str]:
    """
    Enrich one chunk. Raises LLMUnavailable if the server fails; in that case nothing is
    left behind for the chunk (no rejection rows, no enrichment row), so it stays pending.
    """
    self.llm.reset_stats()
    try:
        return self._process_chunk_impl(chunk, context_str)
    except LLMUnavailable:
        # get_pending_files() treats an enrichment row as "attempted"; drop it.
        self.db.delete_enrichment(chunk["chunk_id"])
        raise
    finally:
        st = self.llm.stats
        if st["calls"]:
            logger.info(
                f"Chunk {chunk['chunk_id'][:8]}: {st['calls']} LLM call(s), "
                f"{st['seconds']:.1f}s, tokens in/out "
                f"{st['prompt_tokens']}/{st['completion_tokens']}"
            )

def enrich_single_file(self, file_id: str) -> None:
    """Raises LLMUnavailable (file left pending) if the server is down or stops answering."""
    chunks = self.db.get_chunks_for_file_ordered(file_id)
    if not chunks:
        return
    self.llm.check_health()  # fail fast, before touching any chunk

    chunk_map = {c["chunk_id"]: c["content"] for c in chunks}
    history: Deque[str] = deque(maxlen=3)

    for chunk in chunks:
        ctype = chunk.get("content_type", "prose")
        if ctype in ["table", "math", "code"]:
            parts = []
            prev_id = chunk.get("prev_chunk_id")
            if prev_id and prev_id in chunk_map:
                parts.append(f"PREV: {chunk_map[prev_id][:150]}")
            next_id = chunk.get("next_chunk_id")
            if next_id and next_id in chunk_map:
                parts.append(f"NEXT: {chunk_map[next_id][:150]}")
            context_str = (
                "\n".join(parts) if parts else "No adjacent structural chunks"
            )
        else:
            context_str = "History:\n" + "\n".join([f"- {s}" for s in history])

        success, summary = self._process_chunk(chunk, context_str)

        if (
            success
            and summary
            and not DEFLECTION_PATTERN.search(summary)
            and len(summary.split()) >= MIN_SUMMARY_TOKENS
        ):
            history.append(summary)

class ChromaVerifier:
    COLLECTION = "qa_pairs"

    def __init__(self, persist_directory: str = str(CHROMA_DIR)):
        self._collection = None
        self._model: Optional[SentenceTransformer] = None
        self._ready = False
        if not CHROMA_AVAILABLE or not Path(persist_directory).exists():
            return
        try:
            client = chromadb.PersistentClient(path=persist_directory)
            self._collection = client.get_collection(self.COLLECTION)
            self._ready = self._collection.count() > 0
        except Exception as e:
            logger.debug(f"Chroma collection unavailable: {e}")

    @property
    def ready(self) -> bool:
        return self._ready

    def count(self) -> int:
        if not self._ready:
            return 0
        try:
            return self._collection.count()
        except Exception:
            return 0

    def _get_model(self) -> Optional[SentenceTransformer]:
        if not BGE_AVAILABLE:
            return None
        if self._model is None:
            self._model = models.get_bi_encoder(BGE_MODEL)
        return self._model

    def query(self, text: str, n: int = 3) -> List[Dict]:
        if not self._ready:
            return []
        model = self._get_model()
        if not model:
            return []
        try:
            embedding = model.encode(text, normalize_embeddings=True).tolist()
            results = self._collection.query(
                query_embeddings=[embedding],
                n_results=min(n, self._collection.count()),
                include=["documents", "metadatas", "distances"],
            )
            hits = []
            for qid, doc, meta, dist in zip(
                results.get("ids", [[]])[0],
                results.get("documents", [[]])[0],
                results.get("metadatas", [[]])[0],
                results.get("distances", [[]])[0],
            ):
                hits.append(
                    {
                        "question_id": qid,
                        "document": doc,
                        "score": round(1.0 - dist, 4),
                        "metadata": meta,
                    }
                )
            return hits
        except Exception as e:
            logger.warning(f"ChromaVerifier.query failed: {e}")
            return []

