def enrich_single_file(self, file_id: str) -> None:
    """Raises LLMUnavailable (file left pending) if the server is down or stops answering."""
    chunks = self.db.get_chunks_for_file_ordered(file_id)
    if not chunks:
        return
    self.llm.check_health()  # fail fast, before touching any chunk

    chunk_map = {c["chunk_id"]: c["content"] for c in chunks}
    history: Deque[str] = deque(maxlen=3)

    for chunk in chunks:
        ctype = chunk.get("content_type", "prose")
        if ctype in ["table", "math", "code"]:
            parts = []
            prev_id = chunk.get("prev_chunk_id")
            if prev_id and prev_id in chunk_map:
                parts.append(f"PREV: {chunk_map[prev_id][:150]}")
            next_id = chunk.get("next_chunk_id")
            if next_id and next_id in chunk_map:
                parts.append(f"NEXT: {chunk_map[next_id][:150]}")
            context_str = (
                "\n".join(parts) if parts else "No adjacent structural chunks"
            )
        else:
            context_str = "History:\n" + "\n".join([f"- {s}" for s in history])

        success, summary = self._process_chunk(chunk, context_str)

        if (
            success
            and summary
            and not DEFLECTION_PATTERN.search(summary)
            and len(summary.split()) >= MIN_SUMMARY_TOKENS
        ):
            history.append(summary)

def evaluate_chunk(self, content: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
    text = (content or "").strip()
    text_lower = text.lower()

    if len(text) < 30 or not text_lower:
        return self._result(False, "Too short/Empty", "noise", 0)

    header_text = ""
    for key in ("section_header", "Header 3", "Header 2", "Header 1"):
        val = metadata.get(key)
        if val:
            header_text = str(val).lower()
            break

    if any(exclude in header_text for exclude in self.metadata_excludes):
        return self._result(False, f"Header filter: {header_text}", "metadata", 0)

    if any(text_lower.startswith(ex) for ex in self.content_prefix_excludes):
        return self._result(False, "Forbidden prefix", "other", 0)

    if len(text) < 150:
        if self.patterns["url"].search(text_lower) or self.patterns["doi"].search(
            text_lower
        ):
            return self._result(False, "Citation/Link chunk", "metadata", 0)

    if any(ex in text_lower[:400] for ex in self.content_anywhere_excludes):
        return self._result(False, "Metadata keyword detected", "metadata", 0)

    if self._is_table_of_contents(text):
        return self._result(False, "Detected Table of Contents", "toc", 0)

    alpha_ratio = self._alpha_ratio(text)

    if self.patterns["code_block"].search(text):
        return self._result(True, "Source code block", "code", 85)

    if alpha_ratio < 0.30:
        if self._is_useful_table(text, metadata):
            return self._result(True, "Useful data table", "table", 75)
        return self._result(False, f"Low alpha ({alpha_ratio:.2%})", "metadata", 20)

    quality_score = self._calculate_quality_score(text, metadata, alpha_ratio)
    return self._result(True, "OK", "main_content", quality_score)

def _is_useful_table(self, text: str, metadata: Dict[str, Any]) -> bool:
    lines = text.split("\n")
    table_rows = sum(1 for line in lines if "|" in line)
    header = (metadata.get("section_header") or "").lower()
    if any(x in header for x in ["table of contents", "contents"]):
        return False
    if table_rows > 5 and len(lines) > 0 and (table_rows / len(lines)) > 0.4:
        return True
    return False

def check_duplicate(self, text: str, use_words: bool = False) -> Dict[str, Any]:
    """Check if document is a duplicate."""
    try:
        # Generate simhash
        simhash_hex = self.generate_simhash(text, use_words=use_words)
        simhash_value = int(simhash_hex, 16)
        simhash_obj = Simhash(value=simhash_value)

        # Check for near duplicates in index
        duplicate_file_ids = self.simhash_index.get_near_dups(simhash_obj)

        is_duplicate = len(duplicate_file_ids) > 0

        if is_duplicate:
            self.logger.info(
                f"Duplicate detected: {len(duplicate_file_ids)} similar file(s)"
            )

        return {
            "is_duplicate": is_duplicate,
            "duplicate_file_ids": duplicate_file_ids,
            "simhash": simhash_hex,
        }

    except Exception as e:
        self.logger.error(f"Error checking duplicates: {str(e)}")
        return {"is_duplicate": False, "duplicate_file_ids": [], "simhash": None}

