def parse_dotenv(text: str) -> Dict[str, str]:
    out: Dict[str, str] = {}
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        m = _LINE.match(raw)
        if not m:
            continue
        key, value = m.groups()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
            value = value[1:-1]
        elif " #" in value:  # trailing comment on an unquoted value
            value = value.split(" #", 1)[0].rstrip()
        out[key] = value
    return out

def load_dotenv(path: Optional[Path] = None) -> List[str]:
    """Set every variable from the file that is not already set. Returns the names that were set."""
    if os.environ.get("QP_NO_DOTENV", "").strip().lower() in ("1", "true", "yes"):
        return []
    path = Path(path) if path else find_dotenv()
    if path is None or not path.is_file():
        return []
    loaded = []
    for key, value in parse_dotenv(path.read_text()).items():
        if key not in os.environ:
            os.environ[key] = value
            loaded.append(key)
    if loaded:
        logger.info("Loaded %s from %s", ", ".join(sorted(loaded)), path)
    return loaded

class SerializedConverter:
    """Shares one Docling converter between threads by running one conversion at a time.

    Docling's thread-safety is not documented, so this trades parallel uploads for safety;
    ingestion is dominated by the conversion itself, and the models stay loaded between uploads.
    """

    def __init__(self, converter: Any):
        self._converter = converter
        self._lock = threading.Lock()

    def process_document(self, file_path):
        with self._lock:
            return self._converter.process_document(file_path)

    def convert_to_markdown(self, file_path):
        with self._lock:
            return self._converter.convert_to_markdown(file_path)

    def get_metadata(self, file_path):
        with self._lock:
            return self._converter.get_metadata(file_path)

