@app.post("/api/files/ingest")
@limiter.limit("5/minute")
async def ingest_file(
    request: Request,
    background_tasks: BackgroundTasks,
    current_user: CurrentUser,
    file: UploadFile = File(...),
):
    # .name strips any directory components the client put in the filename.
    safe_name = Path(file.filename or "upload.pdf").name

    head = await file.read(5)
    if head != b"%PDF-":
        raise HTTPException(400, "Only PDF files are accepted.")

    temp_path = DATA_DIR / f"{uuid.uuid4()}_{safe_name}"
    digest = hashlib.sha256(head)
    size = len(head)
    try:
        with open(temp_path, "wb") as f:
            f.write(head)
            while chunk := await file.read(UPLOAD_CHUNK_BYTES):
                size += len(chunk)
                if size > MAX_UPLOAD_BYTES:
                    raise HTTPException(
                        413,
                        f"File too large (limit {MAX_UPLOAD_BYTES // (1024 * 1024)} MB).",
                    )
                digest.update(chunk)
                await run_in_threadpool(f.write, chunk)
    except BaseException:
        temp_path.unlink(missing_ok=True)
        raise
    sha256 = digest.hexdigest()

    # Exact re-upload by the same user: answer immediately, before any Docling work.
    existing = await run_in_threadpool(db.get_file_by_sha256_for_user, current_user, sha256)
    if existing or (current_user, sha256) in _ingesting:
        temp_path.unlink(missing_ok=True)
        if existing:
            return JSONResponse(
                {
                    "detail": f"You already uploaded this file as “{existing['file_name']}”.",
                    "file_id": existing["file_id"],
                    "file_name": existing["file_name"],
                },
                status_code=409,
            )
        return JSONResponse(
            {"detail": "This file is already being processed."}, status_code=409
        )

    _ingesting.add((current_user, sha256))
    background_tasks.add_task(run_ingestion_task, temp_path, current_user, sha256)
    return {
        "status": "processing",
        "message": "File uploaded. Ingestion running in background.",
        "filename": safe_name,
    }

def start_interview(self) -> Optional[str]:
    self.state = InterviewState.IN_PROGRESS
    self.ctx.current_question = self.logic.select_next_question(
        self.ctx.difficulty_label, self.used_ids
    )
    if self.ctx.current_question:
        self.used_ids.add(self.ctx.current_question.id)
        return self.ctx.current_question.text
    return None

def combine_stress_signals(model_stressed: bool, stutter_flag: bool) -> dict:
    if model_stressed and stutter_flag:
        return {
            "level": "highly_stressed",
            "message": "Highly stressed — both vocal patterns and speech disruption detected",
        }
    elif model_stressed and not stutter_flag:
        return {
            "level": "stressed",
            "message": "Stressed — elevated vocal stress indicators detected",
        }
    elif not model_stressed and stutter_flag:
        return {
            "level": "mild",
            "message": "Mild stress indicators — speech disruption detected",
        }
    else:
        return {
            "level": "not_stressed",
            "message": "No significant stress indicators detected",
        }

def run(self) -> None:
    done: Set[str] = set()
    while True:
        files = self.db.get_pending_files(limit=5, exclude=list(done))
        if not files:
            break
        done.update(files)
        server_down = False
        with ThreadPoolExecutor(MAX_WORKERS) as ex:
            futures = {
                ex.submit(self.enrich_single_file, fid): fid for fid in files
            }
            for future in as_completed(futures):
                try:
                    future.result()
                except LLMUnavailable as e:
                    logger.error(f"{e}. Stopping; unfinished files stay pending.")
                    server_down = True
                except Exception as e:
                    logger.error(f"Thread crash: {e}")
        if server_down:
            return

