@classmethod
def _get_bi_encoder(cls) -> Optional[SentenceTransformer]:
    """Shared BGE bi-encoder, or None when it cannot be loaded (retried on the next call)."""
    if not BGE_AVAILABLE:
        return None
    try:
        return models.get_bi_encoder(BGE_MODEL)
    except KeyboardInterrupt:
        logger.warning("Bi-encoder download interrupted by user.")
        raise  # the user wants to quit
    except Exception as e:
        logger.error(f"Failed to load bi-encoder: {e}")
        return None

