def start_interview(self) -> Optional[str]:
    self.state = InterviewState.IN_PROGRESS
    self.ctx.current_question = self.logic.select_next_question(
        self.ctx.difficulty_label, self.used_ids
    )
    if self.ctx.current_question:
        self.used_ids.add(self.ctx.current_question.id)
        return self.ctx.current_question.text
    return None

def select_next_question(
    self, difficulty: str, used_ids: Set[str]
) -> Optional[QuestionObj]:
    candidates = [
        self.questions[qid]
        for qid in self.by_difficulty.get(difficulty.lower(), [])
        if qid not in used_ids
    ]
    if not candidates:
        candidates = [q for q in self.questions.values() if q.id not in used_ids]
    return random.choice(candidates) if candidates else None

# ── Stage 2: Bi-encoder ───────────────────────────────────────────────────

def run(self) -> None:
    done: Set[str] = set()
    while True:
        files = self.db.get_pending_files(limit=5, exclude=list(done))
        if not files:
            break
        done.update(files)
        server_down = False
        with ThreadPoolExecutor(MAX_WORKERS) as ex:
            futures = {
                ex.submit(self.enrich_single_file, fid): fid for fid in files
            }
            for future in as_completed(futures):
                try:
                    future.result()
                except LLMUnavailable as e:
                    logger.error(f"{e}. Stopping; unfinished files stay pending.")
                    server_down = True
                except Exception as e:
                    logger.error(f"Thread crash: {e}")
        if server_down:
            return

@app.delete("/api/files/{file_id}")
def delete_file(file_id: str, current_user: CurrentUser):
    _require_file_owner(current_user, file_id)

    err = _delete_file_everywhere(file_id)
    if err:
        return JSONResponse(
            {
                "detail": "Could not remove this file's embeddings, so the file was kept. "
                "It will be retried automatically; you can also try again.",
                "failed": [file_id],
            },
            status_code=502,
        )
    _retry_pending_deletions()
    return {"message": "File and embeddings deleted successfully"}

